package dev.industrialtechnology.accessories;
import java.util.*;import net.minecraft.block.Block;import net.minecraft.init.Blocks;import net.minecraft.item.ItemStack;import net.minecraft.entity.*;import net.minecraft.entity.player.*;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.util.*;import net.minecraft.enchantment.*;import net.minecraftforge.common.*;import net.minecraftforge.common.util.ForgeDirection;import net.minecraftforge.event.world.ExplosionEvent;
public final class AccessoryWorld {
 public static boolean permitted(EntityPlayerMP p,int x,int y,int z){return p.worldObj.blockExists(x,y,z)&&p.canPlayerEdit(x,y,z,p.worldObj.getBlockMetadata(x,y,z),p.getHeldItem())&&!MinecraftServer.getServer().isBlockProtected(p.worldObj,x,y,z,p)&&!ForgeHooks.onBlockBreakEvent(p.worldObj,p.theItemInWorldManager.getGameType(),p,x,y,z).isCanceled();}
 public static AxisAlignedBB box(int x,int y,int z,int side,int depth){ForgeDirection d=ForgeDirection.getOrientation(side);int n=Math.max(0,depth-1);if(d.offsetX!=0)return AxisAlignedBB.getBoundingBox(x-(d.offsetX>0?n:0),y-1,z-1,x+(d.offsetX<0?n:0),y+1,z+1);if(d.offsetY!=0)return AxisAlignedBB.getBoundingBox(x-1,y-(d.offsetY>0?n:0),z-1,x+1,y+(d.offsetY<0?n:0),z+1);return AxisAlignedBB.getBoundingBox(x-1,y-1,z-(d.offsetZ>0?n:0),x+1,y+1,z+(d.offsetZ<0?n:0));}
 public static void mine(EntityPlayerMP p,ItemStack tool,MovingObjectPosition hit,int depth){World w=p.worldObj;AxisAlignedBB b=box(hit.blockX,hit.blockY,hit.blockZ,hit.sideHit,depth);List<ItemStack> drops=new ArrayList<ItemStack>();boolean action=false;
  for(int x=(int)b.minX;x<=b.maxX;x++)for(int y=(int)b.minY;y<=b.maxY;y++)for(int z=(int)b.minZ;z<=b.maxZ;z++){
   if(!w.blockExists(x,y,z))continue;Block block=w.getBlock(x,y,z);float hardness=block.getBlockHardness(w,x,y,z);if(block==Blocks.air||hardness>=50||hardness<0)continue;if(!CoalFuel.consume(p,tool,8))break;action=true;if(!permitted(p,x,y,z))continue;
   List<ItemStack> loot=EnchantmentHelper.getEnchantmentLevel(Enchantment.silkTouch.effectId,tool)>0&&block.canSilkHarvest(w,p,x,y,z,w.getBlockMetadata(x,y,z))?Arrays.asList(new ItemStack(block,1,w.getBlockMetadata(x,y,z))):block.getDrops(w,x,y,z,w.getBlockMetadata(x,y,z),EnchantmentHelper.getEnchantmentLevel(Enchantment.fortune.effectId,tool));
   if(loot!=null)drops.addAll(loot);w.setBlockToAir(x,y,z);if(w.rand.nextInt(8)==0&&w instanceof WorldServer)((WorldServer)w).func_147487_a("largesmoke",x+.5,y+.5,z+.5,1,0,0,0,0);
  }p.swingItem();if(action){loot(drops,w,hit.blockX,hit.blockY,hit.blockZ);w.playSoundAtEntity(p,"industrialtech:accessories.pedestruct",1,1);}
 }
 public static void loot(List<ItemStack> drops,World w,double x,double y,double z){List<ItemStack> compact=new ArrayList<ItemStack>();for(ItemStack s:drops){if(s==null||s.stackSize<=0)continue;s=s.copy();for(ItemStack t:compact)if(t.isItemEqual(s)&&ItemStack.areItemStackTagsEqual(t,s)){int move=Math.min(s.stackSize,t.getMaxStackSize()-t.stackSize);t.stackSize+=move;s.stackSize-=move;if(s.stackSize==0)break;}if(s.stackSize>0)compact.add(s);}if(!compact.isEmpty())w.spawnEntityInWorld(new EntityLootBall(w,compact,x,y,z));}
 public static void nova(World w,Entity owner,double x,double y,double z,float radius){NovaExplosion explosion=new NovaExplosion(w,owner,x,y,z,radius);if(!MinecraftForge.EVENT_BUS.post(new ExplosionEvent.Start(w,explosion))){explosion.doExplosionA();explosion.doExplosionB(true);}}
 private AccessoryWorld(){}
}
